/**
 * Docusaurus plugin: IDE-style API hover for docs code.
 *
 * Consumes an API symbol index (a names JSON generated by the consuming
 * site; see README for the schema) and provides:
 *
 *  - theme components that stamp `data-api-id` onto resolved identifiers
 *    in code blocks (CodeBlock/Line) and render them (Line/Token),
 *  - the hover runtime (Root): page-wide highlight of every instance of a
 *    symbol plus a signature/docstring tooltip, loaded lazily from the
 *    info JSON,
 *  - webpack wiring that injects the index and plugin options into the
 *    client bundle as aliased JSON modules (`docusaurus-plugin-api-hover/data`
 *    and `docusaurus-plugin-api-hover/config`), which works under both
 *    webpack and rspack.
 *
 * The rehype companion (`docusaurus-plugin-api-hover/rehype`) annotates
 * prose mentions at build time and is registered by the consumer in its
 * markdown config, like any other rehype plugin.
 */
import path from 'path';
import { existsSync, mkdirSync, writeFileSync } from 'fs';
import type { LoadContext, Plugin } from '@docusaurus/types';

export interface PluginOptions {
  /**
   * Path to the names JSON (the consumer's index generator output),
   * relative to the site directory. Shape:
   * {ids: string[], bases?: Record<string, string[]>, version?: string}.
   */
  dataFile: string;
  /** URL the runtime fetches the info JSON from (with ?v=version appended). */
  infoUrl: string;
  /**
   * Id prefixes that win a short-name collision, e.g. ["max."] on a site
   * that indexes both MAX symbols and Python stdlib ids. Keeps secondary
   * id sources from changing existing annotations.
   */
  preferPrefixes: string[];
  /** Language modules to enable for code annotation. Built in: "python". */
  languages: string[];
}

const FALLBACK_CONFIG = {
  infoUrl: '/data/api-hover-info.json',
  preferPrefixes: [] as string[],
  languages: ['python'] as string[],
};

export default function pluginApiHover(context: LoadContext, options: PluginOptions): Plugin {
  const { siteDir } = context;
  const dataPath = path.resolve(siteDir, options.dataFile);
  let effectiveDataPath = dataPath;
  if (!existsSync(dataPath)) {
    // First run before the docs prebuild generated the index: fall back
    // to an empty index so the site still builds, with hover inert.
    effectiveDataPath = path.join(__dirname, 'fallback-data.json');
    console.warn(
      `api-hover: dataFile "${options.dataFile}" not found; ` +
        'hover disabled until the index is generated.',
    );
  }

  // The runtime config (infoUrl, preferPrefixes, languages) is injected as
  // an aliased JSON module, the same mechanism as the data file, so the
  // plugin stays bundler-agnostic (works under webpack and rspack alike).
  const configDir = path.join(siteDir, '.docusaurus');
  const configPath = path.join(configDir, 'api-hover-config.json');
  mkdirSync(configDir, { recursive: true });
  writeFileSync(
    configPath,
    JSON.stringify({
      infoUrl: options.infoUrl || FALLBACK_CONFIG.infoUrl,
      preferPrefixes: options.preferPrefixes ?? [],
      languages: options.languages ?? FALLBACK_CONFIG.languages,
    }),
  );

  // Theme components must share the site's @docusaurus/theme-common copy:
  // useCodeBlockContext only works against the provider created by the
  // same module instance, and bundlers resolve imports from the plugin's
  // real path (which may hold a second copy). Docusaurus dedupes react
  // itself but leaves this to plugins that consume theme-common context.
  let themeCommonAliases: Record<string, string> = {};
  try {
    const internal = require.resolve('@docusaurus/theme-common/internal', {
      paths: [siteDir],
    });
    themeCommonAliases = {
      '@docusaurus/theme-common/internal': internal,
      '@docusaurus/theme-common': path.dirname(path.dirname(internal)),
    };
  } catch {
    console.warn(
      'api-hover: could not resolve @docusaurus/theme-common; ' + 'code annotation may be inert.',
    );
  }

  return {
    name: 'docusaurus-plugin-api-hover',

    getThemePath() {
      return path.join(__dirname, 'theme');
    },

    configureWebpack() {
      // A partial config merged into the site's (object alias form merges
      // per-key with webpack-merge, which is how the site's own aliases
      // are composed). The theme-common alias keeps the plugin's theme
      // components on the site's module instance; the data/config aliases
      // inject the index and the runtime config.
      return {
        resolve: {
          alias: {
            'docusaurus-plugin-api-hover/data': effectiveDataPath,
            'docusaurus-plugin-api-hover/config': configPath,
            ...themeCommonAliases,
          },
        },
      };
    },
  };
}

// Validation is hand-rolled: the site validates plugin options by mixing
// this plugin's schema with its own joi instance, and a second joi copy
// fails with "Cannot mix different versions of joi schemas".
export function validateOptions({ options }: { options: unknown }): PluginOptions {
  if (typeof options !== 'object' || options === null) {
    throw new Error('api-hover: options must be an object');
  }
  const raw = options as Record<string, unknown>;
  if (typeof raw.dataFile !== 'string' || raw.dataFile.length === 0) {
    throw new Error('api-hover: "dataFile" is required (path to the generated names JSON)');
  }
  if (raw.infoUrl !== undefined && typeof raw.infoUrl !== 'string') {
    throw new Error('api-hover: "infoUrl" must be a string');
  }
  for (const key of ['preferPrefixes', 'languages'] as const) {
    const value = raw[key];
    if (
      value !== undefined &&
      (!Array.isArray(value) || value.some((item) => typeof item !== 'string'))
    ) {
      throw new Error(`api-hover: "${key}" must be an array of strings`);
    }
  }
  const invalid = (raw.languages as unknown[] | undefined)?.filter((lang) => lang !== 'python');
  if (invalid && invalid.length > 0) {
    throw new Error(
      `api-hover: unknown languages ${JSON.stringify(invalid)}; ` + 'built in: "python"',
    );
  }
  return {
    dataFile: raw.dataFile,
    infoUrl: (raw.infoUrl as string) || FALLBACK_CONFIG.infoUrl,
    preferPrefixes: (raw.preferPrefixes as string[]) ?? [],
    languages: (raw.languages as string[]) ?? FALLBACK_CONFIG.languages,
  };
}
